import React, { useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { DicomMetadataStore, MODULE_TYPES, useSystem } from '@ohif/core';

import Dropzone from 'react-dropzone';
import filesToStudies from './filesToStudies';

import { extensionManager } from '../../App';

import { WediagButton } from '@ohif/ui';
import { serverInitialization } from '../../../../../extensions/cornerstone/src/services/DatabaseService/backendRequests';

const getLoadButton = (onDrop, text, isDir) => {
  return (
    <Dropzone
      onDrop={onDrop}
      noDrag
    >
      {({ getRootProps, getInputProps }) => (
        <div {...getRootProps()}>
          <WediagButton
            variant="bordered"
            onPress={(e: any) => getRootProps().onClick(e)}
            buttonCategory="md"
          >
            {text}
            {isDir ? (
              <input
                {...getInputProps()}
                webkitdirectory="true"
                mozdirectory="true"
                style={{ display: 'none' }}
              />
            ) : (
              <input
                {...getInputProps()}
                style={{ display: 'none' }}
              />
            )}
          </WediagButton>
        </div>
      )}
    </Dropzone>
  );
};

type LocalProps = {
  modePath: string;
};

function Local({ modePath }: LocalProps) {
  const { servicesManager } = useSystem();
  const { customizationService } = servicesManager.services;
  const navigate = useNavigate();
  const dropzoneRef = useRef();
  const [dropInitiated, setDropInitiated] = React.useState(false);

  const LoadingIndicatorProgress = customizationService.getCustomization(
    'ui.loadingIndicatorProgress'
  );

  // Initializing the dicom local dataSource
  const dataSourceModules = extensionManager.modules[MODULE_TYPES.DATA_SOURCE];
  const localDataSources = dataSourceModules.reduce((acc, curr) => {
    const mods = [];
    curr.module.forEach(mod => {
      if (mod.type === 'localApi') {
        mods.push(mod);
      }
    });
    return acc.concat(mods);
  }, []);

  const firstLocalDataSource = localDataSources[0];
  const dataSource = firstLocalDataSource.createDataSource({});

  const microscopyExtensionLoaded = extensionManager.registeredExtensionIds.includes(
    '@ohif/extension-dicom-microscopy'
  );

  const onDrop = async acceptedFiles => {
    const studies = await filesToStudies(acceptedFiles, dataSource);
    serverInitialization(acceptedFiles);

    const query = new URLSearchParams();

    if (microscopyExtensionLoaded) {
      // TODO: for microscopy, we are forcing microscopy mode, which is not ideal.
      //     we should make the local drag and drop navigate to the worklist and
      //     there user can select microscopy mode
      const smStudies = studies.filter(id => {
        const study = DicomMetadataStore.getStudy(id);
        return (
          study.series.findIndex(s => s.Modality === 'SM' || s.instances[0].Modality === 'SM') >= 0
        );
      });

      if (smStudies.length > 0) {
        smStudies.forEach(id => query.append('StudyInstanceUIDs', id));

        modePath = 'microscopy';
      }
    }

    // Todo: navigate to work list and let user select a mode
    studies.forEach(id => query.append('StudyInstanceUIDs', id));
    query.append('datasources', 'dicomlocal');

    navigate(`/${modePath}?${decodeURIComponent(query.toString())}`);
  };

  // Listen for messages from parent window to get the files given by the application, and the information from the database
  useEffect(() => {
    const { databaseService } = servicesManager.services;

    const handleMessage = async (event: MessageEvent) => {
      const eventData = event.data.payload;
      if (event.data.type === 'APP_NEW_ANALYSIS' || event.data.type === 'APP_LOAD_ANALYSIS') {
        databaseService.setConnectionString(eventData.connectionString);
        databaseService.setImageId(eventData.imageId);
        databaseService.setDatabaseDiscoveryId(eventData.databaseDiscoveryId);
        databaseService.setDBAccessKey(eventData.accessKey);
        eventData.analysisId && databaseService.setAnalysisId(eventData.analysisId);

        setDropInitiated(true);
        console.log('Fetching image content from database for imageId: ', eventData.imageId);

        if (eventData.connectionString && eventData.imageId !== -1) {
          await databaseService.connectToServer();
        }

        databaseService
          .getImageFullContentById()
          .then((imageContent: ArrayBuffer) => {
            console.log(
              'Successfully fetched image content from database, creating file for drop...'
            );
            const file = new File([imageContent], 'dicom.dcm', { type: 'application/dicom' });
            onDrop([file]);
          })
          .catch(error => {
            console.error('Error fetching image content from database:', error);
          });
      }
    };

    window.addEventListener('message', handleMessage);
    return () => window.removeEventListener('message', handleMessage);
  }, []);

  return (
    <Dropzone
      ref={dropzoneRef}
      onDrop={acceptedFiles => {
        setDropInitiated(true);
        onDrop(acceptedFiles);
      }}
      noClick
    >
      {({ getRootProps, isDragActive }) => (
        <div
          {...getRootProps()}
          style={{ width: '100%', height: '100%' }}
        >
          <div className="flex h-screen w-screen justify-center p-6">
            <div
              className={`border-default flex h-4/5 w-4/5 flex-col items-center justify-center rounded-xl border-2 bg-transparent ${isDragActive ? 'border-solid' : 'border-dashed'}`}
            >
              <div className="space-y-6 text-center">
                {dropInitiated ? (
                  <div className="flex flex-col items-center justify-center">
                    <LoadingIndicatorProgress className={'bg-backgroundColor h-full w-full'} />
                  </div>
                ) : (
                  <div className="flex flex-col space-y-6 py-6">
                    <p className="text-default text-3xl">
                      Drag and Drop DICOM files here to load them in the Viewer
                    </p>
                    <p className="text-default text-xl">Or click to </p>
                  </div>
                )}
              </div>
              <div className="flex justify-around space-x-12 pt-6">
                {getLoadButton(onDrop, 'Load files', false)}
                {getLoadButton(onDrop, 'Load folders', true)}
              </div>
            </div>
          </div>
        </div>
      )}
    </Dropzone>
  );
}

export default Local;
