// Dilate bone zone to eventually fill disconnections in dental zone
const binaryDilateDisk = (
  binaryImage: boolean[],
  width: number,
  height: number,
  radius: number = 1
): boolean[] => {
  const result = new Array<boolean>(width * height);

  const offsets: [number, number][] = [];
  // Precompute disk-shaped structuring element
  for (let dy = -radius; dy <= radius; dy++) {
    for (let dx = -radius; dx <= radius; dx++) {
      if (dx * dx + dy * dy <= radius * radius) {
        offsets.push([dx, dy]);
      }
    }
  }

  // Apply binary dilation
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      let found = false;
      for (const [dx, dy] of offsets) {
        if (binaryImage[(y + dy) * width + (x + dx)]) {
          found = true;
          break; // early exit for speed
        }
      }
      result[y * width + x] = found;
    }
  }

  return result;
};

// TODO O(2n) algorithm
// Get spatial clusters in binarized image (groups of pixels connected between them)
const spatialClustering = (binaryImage: boolean[], width: number, height: number): number[][] => {
  const clusters: number[][] = [];
  const visited = new Uint8Array(width * height).fill(0);

  const getNeighbors = (index: number) => {
    const neighbors: number[] = [];
    const x = index % width;
    const y = Math.floor(index / width);

    for (let i = Math.max(0, x - 1); i <= Math.min(width - 1, x + 1); i++) {
      for (let j = Math.max(0, y - 1); j <= Math.min(height - 1, y + 1); j++) {
        const neighborIndex = j * width + i;
        neighbors.push(neighborIndex);
      }
    }

    return neighbors;
  };

  const exploreCluster = (startIndex: number, cluster: number[]) => {
    const queue = [startIndex];

    while (queue.length > 0) {
      const currentIndex = queue.shift();

      if (!visited[currentIndex] && binaryImage[currentIndex]) {
        visited[currentIndex] = 1;
        cluster.push(currentIndex);

        const neighbors = getNeighbors(currentIndex);

        for (const neighborIndex of neighbors) {
          if (!visited[neighborIndex] && binaryImage[neighborIndex]) {
            queue.push(neighborIndex);
          }
        }
      }
    }
  };

  for (let i = 0; i < width * height; i++) {
    if (!visited[i] && binaryImage[i]) {
      const newCluster: number[] = [];
      exploreCluster(i, newCluster);
      clusters.push(newCluster);
    }
  }

  return clusters;
};

export { binaryDilateDisk, spatialClustering };
