import React, { ReactNode, RefObject } from 'react';
import { Button, PressEvent } from '@heroui/react';

const WediagButton = ({
  variant,
  onPress,
  children,
  buttonCategory,
  className = '',
  ref = undefined,
  isDisabled = false,
  type = 'button',
}: {
  variant: 'light' | 'bordered';
  onPress: (e: PressEvent) => void;
  children: ReactNode;
  buttonCategory: 'sm' | 'md' | 'lg' | 'icon';
  className?: string;
  ref?: RefObject<HTMLButtonElement | null>;
  isDisabled?: boolean;
  type?: 'button' | 'submit';
}) => {
  return (
    <Button
      className={`button-${buttonCategory} ${className} ${variant === 'bordered' ? 'border-2' : ''} ${isDisabled ? 'opacity-50' : ''}`}
      variant={variant}
      isIconOnly={buttonCategory === 'icon'}
      onPress={onPress}
      data-hover={false}
      isDisabled={isDisabled}
      ref={ref}
      type={type}
    >
      {children}
    </Button>
  );
};

export default WediagButton;
