import { NumberPair, Points, XYXPos } from 'extensions/cornerstone/src/types/Panoramic';
import { Point3 } from '@cornerstonejs/core/types';
import { getMax } from './mathUtils';
import { polynomialLSF } from './computeDentalCurveUtils';
import { getParameters } from './cbctUtils';

const interpolateTwoPoints = (v1: number, v2: number, t: number) => {
  return Math.round(t * v1 + (1 - t) * v2);
};

const interpolateThreePoints = (
  v1: number,
  v2: number,
  vMid: number,
  tMin: number,
  tMax: number
) => {
  return Math.round(tMin * v1 + (tMax - tMin) * vMid + (1 - tMax) * v2);
};

// Get dentascan section at abscissa i for a polynomial fitting curve lsf.
// Dicom of the dentascan desired is defined by its dicomDimensions and its scalarData
export const getDentascanSection = (
  scalarData: ArrayLike<number>,
  dimensions: Point3,
  [minLayer, maxLayer]: NumberPair,
  dentascanWidth: number,
  minPoint: NumberPair,
  normal: NumberPair
): [Float32Array<ArrayBuffer>, boolean[]] => {
  const [layerWidth, layerHeight, _] = dimensions;
  const layerSize = layerWidth * layerHeight;
  const nbLayers = maxLayer - minLayer;

  const [vxNormal, vyNormal] = normal;
  // Get values of point along normal between min and max
  const dentascan = new Float32Array(dentascanWidth * nbLayers).fill(-1000);
  const dentascanValidMask = new Array<boolean>(dentascanWidth);
  for (let i = 0; i < dentascanWidth; i++) {
    const xi: number = minPoint[0] + i * vxNormal;
    const xj: number = minPoint[0] + (i + 1) * vxNormal;
    const yi: number = minPoint[1] + i * vyNormal;
    const yj: number = minPoint[1] + (i + 1) * vyNormal;

    dentascanValidMask[i] =
      xi >= 0 &&
      xi < layerWidth &&
      yi >= 0 &&
      yi < layerHeight &&
      xj >= 0 &&
      xj < layerWidth &&
      yj >= 0 &&
      yj < layerHeight;
    if (!dentascanValidMask[i]) {
      continue;
    }
    const [pxi, pxj, pyi, pyj] = [xi, xj, yi, yj].map(Math.floor);
    for (let layer = 0; layer < nbLayers; layer++) {
      const dicomI: number = scalarData[(minLayer + layer) * layerSize + pyi * layerWidth + pxi];
      const idx: number = layer * dentascanWidth + i;
      if (pxi === pxj && pyi === pyj) {
        // Same pixel
        dentascan[idx] = dicomI;
      } else {
        const dicomJ: number = scalarData[(minLayer + layer) * layerSize + pyj * layerWidth + pxj];
        if (pyi === pyj) {
          // Horizontal interpolation
          const tx: number = pxi < pxj ? (1 - (xi % 1)) / vxNormal : -(xi % 1) / vxNormal; // Ratio of segment within pxi
          dentascan[idx] = interpolateTwoPoints(dicomI, dicomJ, tx);
        } else if (pxi === pxj) {
          // Vertical interpolation
          const ty: number = pyi < pyj ? (1 - (yi % 1)) / vyNormal : -(yi % 1) / vyNormal; // Ratio of segment within pyi
          dentascan[idx] = interpolateTwoPoints(dicomI, dicomJ, ty);
        } else {
          // Diagonal interpolation
          const tx: number = pxi < pxj ? (1 - (xi % 1)) / vxNormal : -(xi % 1) / vxNormal;
          const ty: number = pyi < pyj ? (1 - (yi % 1)) / vyNormal : -(yi % 1) / vyNormal;
          const dicomK: number =
            tx < ty
              ? scalarData[(minLayer + layer) * layerSize + pyi * layerWidth + pxj]
              : scalarData[(minLayer + layer) * layerSize + pyj * layerWidth + pxi];
          const [tMin, tMax] = [tx, ty].sort();
          dentascan[idx] = interpolateThreePoints(dicomI, dicomJ, dicomK, tMin, tMax);
        }
      }
    }
  }

  return [dentascan, dentascanValidMask];
};

const computeDentascansNoAliasing = (
  scalarData: ArrayLike<number>,
  dimensions: Point3,
  [minLayer, maxLayer]: NumberPair,
  dentascanWidth: number,
  points: Points
): [Float32Array<ArrayBuffer>[], boolean[][]] => {
  let { outerPoints: minPoints, normals } = points;
  const nbDentascans = minPoints.length;
  const dentascans = new Array<Float32Array<ArrayBuffer>>(nbDentascans);
  const validMasks = new Array<boolean[]>(nbDentascans);
  // Iteration on normals and outerPoints i.e. each curvePoint is associated with one column in the panoramic
  for (let i = 0; i < nbDentascans; i++) {
    const [dentascan, validMask] = getDentascanSection(
      scalarData,
      dimensions,
      [minLayer, maxLayer],
      dentascanWidth,
      minPoints[i],
      normals[i]
    );
    dentascans[i] = dentascan;
    validMasks[i] = validMask;
  }

  return [dentascans, validMasks];
};

const computeDentascansAliasing = (
  scalarData: ArrayLike<number>,
  dimensions: Point3,
  [minLayer, maxLayer]: NumberPair,
  dentascanWidthAliased: number,
  points: Points
): [Float32Array<ArrayBuffer>[], boolean[][]] => {
  let { outerPoints: minPoints, normals } = points;
  const w = 2 * dentascanWidthAliased;
  normals = normals.map(([vx, vy]) => [vx / 2, vy / 2]);
  const nbDentascansAliased = Math.floor(minPoints.length / 2);
  const dentascans = new Array<Float32Array<ArrayBuffer>>(nbDentascansAliased);
  const validMasks = new Array<boolean[]>(nbDentascansAliased);
  // Iteration on normals and minPoints i.e. each curvePoint is associated with one column in the panoramic
  for (let i = 0; i < nbDentascansAliased; i++) {
    const [minPoint1, minPoint2] = [minPoints[i * 2], minPoints[i * 2 + 1]];
    const [normal1, normal2] = [normals[i * 2], normals[i * 2 + 1]];
    const [dentascan1, validMask1] = getDentascanSection(
      scalarData,
      dimensions,
      [minLayer, maxLayer],
      w,
      minPoint1,
      normal1
    );
    const [dentascan2, validMask2] = getDentascanSection(
      scalarData,
      dimensions,
      [minLayer, maxLayer],
      w,
      minPoint2,
      normal2
    );
    // Apply aliasing
    const nbLayers = maxLayer - minLayer;
    const newDentascan = new Float32Array(dentascanWidthAliased * nbLayers).fill(NaN);
    const newValidMask = new Array<boolean>(dentascanWidthAliased);
    for (let j = 0; j < dentascanWidthAliased; j++) {
      const idx = 2 * j;
      const validMaskSum =
        +validMask1[idx] + +validMask1[idx + 1] + +validMask2[idx] + +validMask2[idx + 1];
      newValidMask[j] = validMaskSum !== 0;
      if (!validMaskSum) {
        continue;
      }

      for (let l = 0; l < nbLayers; l++) {
        // Size is doubled in dentascan and nextDentascan so index is multiplied by 2
        const idx = 2 * (l * dentascanWidthAliased + j);
        const dentascanSum =
          dentascan1[idx] + dentascan1[idx + 1] + dentascan2[idx] + dentascan2[idx + 1];
        newDentascan[l * dentascanWidthAliased + j] = Math.floor(dentascanSum / validMaskSum);
        // TODO interval and minPoint are not changed?
      }
    }
    dentascans[i] = newDentascan;
    validMasks[i] = newValidMask;
  }

  return [dentascans, validMasks];
};

// I want to ensure that the polynomial does not diverge beyond the teeth zone.
// The goal is to smooth out and converge the polynomial on the center outside the given interval while
// preserving its original behavior within the interval [minX, maxX].
// To achieve this, I use a modified function incorporating two sigmoid functions.
const getDentalLiss = (
  f: (x: number) => number,
  minX: number,
  maxX: number,
  middlePoint: number
) => {
  // a1 and a2 are smoothing parameters.
  const a1 = 0.1;
  const a2 = 0.1;
  // c0 is the convergence on -inf, and c1 and +inf
  const c0 = middlePoint;
  const c1 = middlePoint;

  return (layer: number) => {
    const sigmoidLeft = 1 / (1 + Math.exp(-a1 * (layer - minX)));
    const sigmoidRight = 1 / (1 + Math.exp(a2 * (layer - maxX)));

    return f(layer) * sigmoidLeft * sigmoidRight + c0 * (1 - sigmoidLeft) + c1 * (1 - sigmoidRight);
  };
};

const getDentalCurve = (dentascanMask: boolean[], dimensions: [number, number]) => {
  const [dentascanWidth, dentascanHeight] = dimensions;
  const middlePoint = Math.floor(dentascanWidth / 2);

  let lsfDentalLiss = (_: number) => middlePoint;
  if (!dentascanMask.some(v => v)) {
    return lsfDentalLiss;
  }

  const onlyTeethIndex = [];
  let minX = Infinity;
  let maxX = -Infinity;
  for (let i = 0; i < dentascanMask.length; i++) {
    if (!dentascanMask[i]) {
      continue;
    }
    const x = Math.floor(i / dentascanWidth);
    const y = i % dentascanWidth;
    // minX and maxX where value is not -1000
    minX = x < minX ? x : minX;
    maxX = x > maxX ? x : maxX;
    onlyTeethIndex.push({ x, y });
  }
  // Add points along the center of the dentascan to reduce the deformation of the curve
  for (let l = 0; l < dentascanHeight; l += 10) {
    onlyTeethIndex.push({ x: l, y: middlePoint });
  }

  // Curve fitting on a degree 3 polynomial
  // TODO order should depend on error for the curve fitting
  const lsfDentalCurve = polynomialLSF(onlyTeethIndex, 3);

  if (!lsfDentalCurve.equation.some(value => isNaN(value))) {
    lsfDentalLiss = getDentalLiss(lsfDentalCurve.predict, minX, maxX, middlePoint);
  }

  return lsfDentalLiss;
};

const getDentascanMask = (
  dentascan: Float32Array<ArrayBuffer>,
  offsetMin: number,
  offsetMax: number,
  thresholdValue: number
): boolean[] => {
  const dentascanMask = new Array<boolean>(dentascan.length).fill(false);
  for (let i = offsetMin; i < offsetMax; i++) {
    // Dentascan is thresholded to get only bone area
    dentascanMask[i] = dentascan[i] > thresholdValue;
  }

  return dentascanMask;
};

const getDentalCurvesPointsXY = (
  dentascans: Float32Array<ArrayBuffer>[],
  [minLayer, maxLayer]: NumberPair,
  minPoints: NumberPair[],
  normals: NumberPair[],
  [minTissueLayer, maxTissueLayer]: NumberPair,
  spacing: number,
  mode: string = 'curveAIP',
  thresholdValue: number = 1100,
  dentalCurveAipStep: number = 2,
  dentalCurvesStep: number = 1,
  axialCurvesStep: number = 1
): XYXPos[] => {
  const { dentascanWidth, dentalCurveAipWidth } = getParameters(spacing);
  const nbLayers = maxLayer - minLayer;
  const offsetMin = (minTissueLayer - minLayer) * dentascanWidth;
  const offsetMax = (maxTissueLayer - minLayer) * dentascanWidth;
  const panoramicWidth = dentascans.length;
  const nbDentalCurves = Math.floor(panoramicWidth / dentalCurvesStep);
  const nbAxialCurves = Math.floor(nbLayers / axialCurvesStep);

  let dentalCurvesPoints: Float32Array;
  if (mode === 'curveAIP') {
    // Precompute the values
    dentalCurvesPoints = new Float32Array(panoramicWidth * nbLayers);
    dentascans.forEach((dentascan, idx) => {
      const dentascanMask = getDentascanMask(dentascan, offsetMin, offsetMax, thresholdValue);
      const dentascanCurve = getDentalCurve(dentascanMask, [dentascanWidth, nbLayers]);
      for (let layer = 0; layer < nbLayers; layer++) {
        dentalCurvesPoints[idx * nbLayers + layer] = dentascanCurve(layer);
      }
    });
  }

  const dentalCurvesPointsXY: XYXPos[] = new Array(nbDentalCurves * nbAxialCurves).fill(null);
  for (let i = 0; i < nbDentalCurves; i++) {
    const idx = dentalCurvesStep * i;
    const dentascan = dentascans[idx];
    const idxInf = Math.max(idx - Math.floor(dentalCurveAipWidth / 2), 0);
    const idxSup = Math.min(idx + Math.floor(dentalCurveAipWidth / 2), panoramicWidth - 1);
    const nbDentascansForMIP = Math.floor((idxSup - idxInf) / dentalCurveAipStep) + 1;

    let dentalCurve: (x: number) => number;
    if (mode === 'default') {
      const dentascanMask = getDentascanMask(dentascan, offsetMin, offsetMax, thresholdValue);
      dentalCurve = getDentalCurve(dentascanMask, [dentascanWidth, nbLayers]);
    } else if (mode === 'valueMIP') {
      const dentascansForMIP = new Array<Float32Array>(nbDentascansForMIP);
      for (let j = 0; j < nbDentascansForMIP; j++) {
        const dentascanIdx = idxInf + j * dentalCurveAipStep;
        dentascansForMIP[j] = dentascans[dentascanIdx];
      }
      const dentascanMIP = new Float32Array(dentascan.length);
      for (let j = 0; j < dentascan.length; j++) {
        dentascanMIP[j] = getMax(dentascansForMIP.map(dentascanScalar => dentascanScalar[j]));
      }
      const dentascanMask = getDentascanMask(dentascan, offsetMin, offsetMax, thresholdValue);
      dentalCurve = getDentalCurve(dentascanMask, [dentascanWidth, nbLayers]);
    }

    const dentascanMinPoint = minPoints[idx];
    const [dentascanVxNormal, dentascanVyNormal] = normals[idx];
    for (let l = 0; l < nbAxialCurves; l++) {
      const layer = axialCurvesStep * l;

      let xPosInDentascan: number;
      if (mode === 'curveAIP') {
        const xPosInDentascans = new Float32Array(nbDentascansForMIP);
        for (let j = 0; j < nbDentascansForMIP; j++) {
          const dentascanIdx = idxInf + j * dentalCurveAipStep;
          xPosInDentascans[j] = dentalCurvesPoints[dentascanIdx * nbLayers + layer];
        }
        xPosInDentascan = xPosInDentascans.reduce((a, b) => a + b, 0) / xPosInDentascans.length;
      } else {
        // default or valueMIP
        xPosInDentascan = dentalCurve(layer);
      }
      if (xPosInDentascan < 0) {
        xPosInDentascan = 0;
      } else if (xPosInDentascan > dentascanWidth) {
        xPosInDentascan = dentascanWidth;
      }
      const x = dentascanMinPoint[0] + xPosInDentascan * dentascanVxNormal;
      const y = dentascanMinPoint[1] + xPosInDentascan * dentascanVyNormal;

      dentalCurvesPointsXY[l * nbDentalCurves + i] = { x, y, xpos: xPosInDentascan };
    }
  }

  return dentalCurvesPointsXY;
};

export { computeDentascansNoAliasing, computeDentascansAliasing, getDentalCurvesPointsXY };
