const derivative = (f: (value: number) => number, x: number, dx: number = 1e-5) => {
  return (f(x + dx) - f(x)) / dx;
};

const getSlopeVector = (slope: number) => {
  const [vx, vy] = [1, slope];
  const vLength = Math.sqrt(1 + slope * slope);
  return [vx / vLength, vy / vLength];
};

const getTangentVector = (f: (value: number) => number, x: number) => {
  const tangentSlope = derivative(f, x);
  return getSlopeVector(tangentSlope);
};

const getNormalVector = (f: (value: number) => number, x: number) => {
  const tangentVector = getTangentVector(f, x);
  const [vx, vy] = [-tangentVector[1], tangentVector[0]];
  return [vx, vy];
};

const getMax = (arr: ArrayLike<number>): number => {
  let len = arr.length;
  let max = -Infinity;

  while (len--) {
    max = arr[len] > max ? arr[len] : max;
  }
  return max;
};

export { getTangentVector, getNormalVector, getMax };
