import { PubSubService } from '@ohif/core';
import { ImplantData, NumberPair, Points, Position } from '../../types/Panoramic';
import { dbTransport } from './databaseTransport';

interface ResultInfo3d {
  id?: number;
  analyze_id?: number;
  segmented_anatomy?: { type: 'Buffer'; data: number[] };
  segmented_diseases?: { type: 'Buffer'; data: number[] };
  panoramic?: { type: 'Buffer'; data: number[] };
  diseases: { pos: Position; subtype: string; confidence: number }[];
  implants?: ImplantData[];
  metadata: {
    dentascan_thickness: number;
    min_max_tissue_layer: NumberPair;
    points: Points;
  };
}

export interface ResultInfoFull {
  id?: number;
  image_id: number;
  date: string;
  api_version: string;
  app_version: string;
  analyze_uuid: string;
  status: 'ANALYSED' | 'IN_PROGRESS' | 'VALIDATED';
  examIndication: string;
  type: number;
  data3d: ResultInfo3d;
}

export default class DatabaseService extends PubSubService {
  private accessKey: string = '';
  private connectionString: string = '';
  private imageId: number = -1;
  private analysisId: number = -1;
  private requestStatus: string = ''; // Is used to displays informations in the Header
  private analysisReady: boolean = false; // Used to know if Add Implant can be clicked or not
  private databaseDiscoveryId: string = '';
  private dbAccessKey: string = '';

  static EVENTS = {
    REQUEST_STATUS_CHANGED: 'REQUEST_STATUS_CHANGED',
    ANALYSIS_READY_CHANGED: 'ANALYSIS_READY_CHANGED',
  };

  public static REGISTRATION = {
    name: 'databaseService',
    create: (): DatabaseService => {
      return new DatabaseService();
    },
  };

  constructor() {
    super(DatabaseService.EVENTS);
  }

  public setRequestStatus = (newRequestStatus: string) => {
    this.requestStatus = newRequestStatus;
    this._broadcastEvent(DatabaseService.EVENTS.REQUEST_STATUS_CHANGED, newRequestStatus);
  };

  public getRequestStatus = () => {
    return this.requestStatus;
  };

  public setAnalysisReady = (analysisReady: boolean) => {
    this.analysisReady = analysisReady;
    this._broadcastEvent(DatabaseService.EVENTS.ANALYSIS_READY_CHANGED, analysisReady);
  };

  public isAnalysisReady = () => {
    return this.analysisReady;
  };

  public setAccessKey = (accessKey: string) => {
    this.accessKey = accessKey;
  };

  public getAccessKey = () => {
    return this.accessKey;
  };

  public setConnectionString = (connectionString: string) => {
    this.connectionString = connectionString;
  };

  public getConnectionString = () => {
    return this.connectionString;
  };

  public setImageId = (imageId: number) => {
    this.imageId = imageId;
  };

  public getImageId = () => {
    return this.imageId;
  };

  public setAnalysisId = (analysisId: number) => {
    this.analysisId = analysisId;
  };

  public getAnalysisId = () => {
    return this.analysisId;
  };

  public setDatabaseDiscoveryId = (databaseDiscoveryId: string) => {
    this.databaseDiscoveryId = databaseDiscoveryId;
  };

  public getDatabaseDiscoveryId = () => {
    return this.databaseDiscoveryId;
  };

  public setDBAccessKey = (dbAccessKey: string) => {
    this.dbAccessKey = dbAccessKey;
  };

  public getDBAccessKey = () => {
    return this.dbAccessKey;
  };

  private isValidAnalysis = (): boolean => {
    return this.connectionString !== '' && this.analysisId !== -1;
  };

  public connectToServer = async () => {
    try {
      await dbTransport.connect(this.connectionString, this.dbAccessKey, this.databaseDiscoveryId);
    } catch (e) {
      const message = e instanceof Error ? e.message : '';
      const wasCancelled = message === 'Disconnected' || message === 'Connection closed';
      if (!wasCancelled) {
        console.error('Database connection failed:', e);
        if (message === 'Authentication denied') {
          console.error('Authentication denied');
        } else if (message === 'Approval timeout') {
          console.error('Approval timeout');
        } else {
          console.error('Generic error');
        }
      }
    }
  };

  public getImageContentById = async (): Promise<string | null> => {
    if (this.connectionString === '' || this.imageId === -1) {
      return null;
    }

    try {
      const blob = await dbTransport.requestBlobResponse(
        'getImageContentById',
        { id: this.imageId },
        'imageDownload'
      );
      return URL.createObjectURL(blob);
    } catch (e) {
      throw new Error(`Error in getImageContentById: ${e}`);
    }
  };

  public createAnalysis = async (analysisUuid: string): Promise<boolean | null> => {
    if (this.connectionString === '' || this.imageId === -1) {
      return null;
    }

    const emptyAnalysis: ResultInfoFull = {
      image_id: this.imageId,
      date: new Date().toISOString(),
      api_version: '1.1.0',
      app_version: '1.0.1',
      analyze_uuid: analysisUuid,
      status: 'ANALYSED',
      examIndication: '',
      type: 3,
      data3d: {
        diseases: [],
        metadata: {
          dentascan_thickness: 0,
          min_max_tissue_layer: [0, 0],
          points: {
            controlPoints: [],
            curvePoints: [],
            innerPoints: [],
            normals: [],
            outerPoints: [],
          },
        },
      },
    };

    try {
      const insertedId = await dbTransport.send<number>('addAnalyze', emptyAnalysis);
      if (insertedId <= 0) {
        return false;
      }
      this.analysisId = insertedId;
      return true;
    } catch (e) {
      throw new Error(`Error in createAnalysis: ${e}`);
    }
  };

  public updateImageDescription = async (description: string): Promise<boolean | null> => {
    if (!this.isValidAnalysis()) {
      return null;
    }

    try {
      return await dbTransport.send('updateImageDescription', { id: this.imageId, description });
    } catch (e) {
      throw new Error(`Error in updateImageDescription: ${e}`);
    }
  };

  public getImageDescription = async (): Promise<string> => {
    if (!this.isValidAnalysis()) {
      return '';
    }

    try {
      const description = await dbTransport.send<string>('getImageDescription', {
        id: this.imageId,
      });
      return description;
    } catch (e) {
      throw new Error(`Error in getImageDescription: ${e}`);
    }
  };

  public modifyAnalyzeSegmentedAnatomy = async (
    segmented_anatomy: Uint8Array
  ): Promise<boolean | null> => {
    if (!this.isValidAnalysis()) {
      return null;
    }

    try {
      await dbTransport.send('modifyAnalyzeSegmentedAnatomy', {
        id: this.analysisId,
        segmented_anatomy,
      });
      return true;
    } catch (e) {
      console.error('websocket error in modifyAnalyzeSegmentedAnatomy: ', e);
      throw new Error(`Error in modifyAnalyzeSegmentedAnatomy: ${e}`);
    }
  };

  public modifyAnalyzeSegmentedDiseases = async (
    segmented_diseases: Uint8Array
  ): Promise<boolean | null> => {
    if (!this.isValidAnalysis()) {
      return null;
    }

    try {
      await dbTransport.send('modifyAnalyzeSegmentedDiseases', {
        id: this.analysisId,
        segmented_diseases,
      });
      return true;
    } catch (e) {
      throw new Error(`Error in modifyAnalyzeSegmentedDiseases: ${e}`);
    }
  };

  public modifyAnalyzePanoramic = async (panoramic: Float32Array): Promise<boolean | null> => {
    if (!this.isValidAnalysis()) {
      return null;
    }

    try {
      await dbTransport.send('modifyAnalyzePanoramic', { id: this.analysisId, panoramic });
      return true;
    } catch (e) {
      throw new Error(`Error in modifyAnalyzePanoramic: ${e}`);
    }
  };

  public modifyAnalyzeDiseases = async (
    diseases: ResultInfo3d['diseases']
  ): Promise<boolean | null> => {
    if (!this.isValidAnalysis()) {
      return null;
    }

    try {
      await dbTransport.send('modifyAnalyzeDiseases', { id: this.analysisId, diseases });
      return true;
    } catch (e) {
      throw new Error(`Error in modifyAnalyzeDiseases: ${e}`);
    }
  };

  public modifyAnalyzeImplants = async (implants: ImplantData[]): Promise<boolean | null> => {
    if (!this.isValidAnalysis()) {
      return null;
    }

    try {
      await dbTransport.send('modifyAnalyzeImplants', { id: this.analysisId, implants });
      return true;
    } catch (e) {
      throw new Error(`Error in modifyAnalyzeImplants: ${e}`);
    }
  };

  public modifyAnalyzeMetadata = async (
    metadata: ResultInfo3d['metadata']
  ): Promise<boolean | null> => {
    if (!this.isValidAnalysis()) {
      return null;
    }

    try {
      await dbTransport.send('modifyAnalyzeMetadata', { id: this.analysisId, metadata });
      return true;
    } catch (e) {
      throw new Error(`Error in modifyAnalyzeMetadata: ${e}`);
    }
  };

  public modifyAnalyzeStatus = async (
    status: ResultInfoFull['status']
  ): Promise<boolean | null> => {
    if (!this.isValidAnalysis()) {
      return null;
    }

    try {
      await dbTransport.send('modifyAnalyzeStatus', { id: this.analysisId, status });
      return true;
    } catch (e) {
      throw new Error(`Error in modifyAnalyzeStatus: ${e}`);
    }
  };

  public modifyAnalyzeExamIndication = async (examIndication: string): Promise<boolean | null> => {
    if (!this.isValidAnalysis()) {
      return null;
    }

    try {
      await dbTransport.send('modifyAnalyzeExamIndication', {
        id: this.analysisId,
        examIndication,
      });
      return true;
    } catch (e) {
      throw new Error(`Error in modifyAnalyzeExamIndication: ${e}`);
    }
  };

  public getAnalyzeById = async (): Promise<ResultInfoFull | null> => {
    if (!this.isValidAnalysis()) {
      return null;
    }

    try {
      return await dbTransport.send('getAnalyzeById', { id: this.analysisId });
    } catch (e) {
      throw new Error(`Error in getAnalyzeById: ${e}`);
    }
  };

  public getAnalyzeByImageId = async (): Promise<ResultInfoFull | null> => {
    if (this.connectionString === '' || this.imageId === -1) {
      return null;
    }

    try {
      return await dbTransport.send('getAnalyzeByImageId', { id: this.imageId });
    } catch (e) {
      throw new Error(`Error in getAnalyzeByImageId: ${e}`);
    }
  };

  public getImageFullContentById = async (): Promise<ArrayBuffer> => {
    try {
      const blob = await dbTransport.requestBlobResponse(
        'getImageFullContentById',
        { id: this.imageId },
        'imageDownload'
      );
      return blob.arrayBuffer();
    } catch (e) {
      throw new Error(`Error in getImageFullContentById: ${e}`);
    }
  };
}
