import React, { ComponentType, useEffect, useState } from 'react';

const teethFullComponents: {
  [tooth: number]: () => Promise<{ default: ComponentType<{ fill: string; scale: number }> }>;
} = {
  11: () => import('./Full11'),
  12: () => import('./Full12'),
  13: () => import('./Full13'),
  14: () => import('./Full14'),
  15: () => import('./Full15'),
  16: () => import('./Full16'),
  17: () => import('./Full17'),
  18: () => import('./Full18'),
  21: () => import('./Full21'),
  22: () => import('./Full22'),
  23: () => import('./Full23'),
  24: () => import('./Full24'),
  25: () => import('./Full25'),
  26: () => import('./Full26'),
  27: () => import('./Full27'),
  28: () => import('./Full28'),
  31: () => import('./Full31'),
  32: () => import('./Full32'),
  33: () => import('./Full33'),
  34: () => import('./Full34'),
  35: () => import('./Full35'),
  36: () => import('./Full36'),
  37: () => import('./Full37'),
  38: () => import('./Full38'),
  41: () => import('./Full41'),
  42: () => import('./Full42'),
  43: () => import('./Full43'),
  44: () => import('./Full44'),
  45: () => import('./Full45'),
  46: () => import('./Full46'),
  47: () => import('./Full47'),
  48: () => import('./Full48'),
};

const TeethManager = ({
  toothNumber,
  fill,
  scale,
}: {
  toothNumber: number;
  fill: string;
  scale: number;
}) => {
  const [DynamicComponent, setDynamicComponent] = useState<ComponentType<{
    fill: string;
    scale: number;
  }> | null>(null);

  // Load the correct component depending on toothNumber and full arguments
  useEffect(() => {
    const loadComponent = async (): Promise<void> => {
      const importer = teethFullComponents[toothNumber];
      if (!importer) {
        console.error(`No component Full${toothNumber}`);
        setDynamicComponent(null);
        return;
      }

      try {
        const { default: Component } = await importer();
        setDynamicComponent(() => Component);
      } catch (error) {
        console.error(`Error loading component Full${toothNumber}:`, error);
        setDynamicComponent(null);
      }
    };

    loadComponent();
  }, [toothNumber]);

  return (
    DynamicComponent && (
      <DynamicComponent
        fill={fill}
        scale={scale}
      />
    )
  );
};

export default TeethManager;
