type BufferJson = { type: 'Buffer'; data: number[] };

const isNumericKeyObject = (value: Record<string, unknown>): boolean => {
  const keys = Object.keys(value);
  return keys.length > 0 && keys.every(key => /^\d+$/.test(key));
};

/** Parses DB / legacy WebRTC binary fields into a Node Buffer. */
const bufferFromStoredBinary = (value: unknown, legacyNestedKey?: string): Buffer => {
  if (value == null) {
    throw new Error('Missing binary field');
  }

  if (typeof value === 'object') {
    const candidate = value as Record<string, unknown>;

    if (candidate.type === 'Buffer' && Array.isArray(candidate.data)) {
      return Buffer.from(candidate.data as number[]);
    }

    if (legacyNestedKey && candidate[legacyNestedKey] != null) {
      return bufferFromStoredBinary(candidate[legacyNestedKey]);
    }

    if (isNumericKeyObject(candidate)) {
      const values = Object.keys(candidate)
        .sort((a, b) => Number(a) - Number(b))
        .map(key => Number(candidate[key]));
      const looksLikeFloatData = values.some(
        value => !Number.isInteger(value) || value < 0 || value > 255
      );
      if (looksLikeFloatData) {
        return Buffer.from(new Float32Array(values).buffer);
      }
      return Buffer.from(values);
    }
  }

  throw new Error('Invalid binary field format');
};

const hexToRgbValue = (hex: string) => {
  // Remove the hash symbol, if present
  hex = hex.replace(/^#/, '');

  // Parse the hex values into their respective components
  const r: number = parseInt(hex.substring(0, 2), 16);
  const g: number = parseInt(hex.substring(2, 4), 16);
  const b: number = parseInt(hex.substring(4, 6), 16);

  // Return the RGB values as an object
  return [r, g, b];
};

const rgbToHexValue = ([r, g, b]: number[]): string => {
  const toHex = (value: number): string => {
    const hex = value.toString(16).toUpperCase();
    return hex.length === 1 ? '0' + hex : hex;
  };

  return `#${toHex(r)}${toHex(g)}${toHex(b)}`;
};

