const transferVolumeOnDrop = async (acceptedFiles: File[], accessKey: string) => {
  try {
    const zip = new JSZip();
    for (const i in acceptedFiles) {
      const file = acceptedFiles[i];
      const buffer = await file.arrayBuffer();
      const ext = file.name.split('.').pop();
      zip.file(`${i}.${ext}`, buffer, {
        binary: true,
        compression: 'DEFLATE',
        compressionOptions: { level: 6 },
      });
    }

    const zipBlob = await zip.generateAsync({ type: 'blob', compression: 'DEFLATE' });
    const formData = new FormData();
    formData.append('input_file', zipBlob, 'dicom.zip');

    const url = `${baseURL}/cbct/`;
    const headers = accessKey ? { Authorization: 'Bearer ' + accessKey } : undefined;
    const config: AxiosRequestConfig = { method: 'post', url, headers, data: formData };
    const response: AxiosResponse<{ uuid: string }> = await axios(config);
    console.log('Server response for volume transfer', response.data);

    return response;
  } catch (error) {
    console.error('Server error for volume transfer', error);
  }
};

