const postConfig = async (accessKey: string, segmentationId: string, segmentIndex: number) => {
  const { segmentationService } = servicesManager.services;
  try {
    const segmentation = segmentationService.getSegmentation(segmentationId);
    if (!segmentation) {
      return;
    }

    const type = segmentationId === 'anatomy' ? 'ANATOMY' : 'DISEASE';
    const { label } = segmentation.segments[segmentIndex];
    const color = segmentationService.getSegmentColor('axial', segmentationId, segmentIndex);
    const formData: FormData = new FormData();
    formData.append('type', type);
    formData.append('label', label);
    formData.append('color', rgbToHexValue(color));
    formData.append('segment_index', String(segmentIndex));

    const url = `${baseURL}/cbct/config/`;
    const headers = accessKey ? { Authorization: 'Bearer ' + accessKey } : undefined;
    const config: AxiosRequestConfig = { method: 'post', url, headers, data: formData };
    const response = await axios(config);
    console.log('Server response for segment config export', response.data);

    return response;
  } catch (error) {
    console.error('Server error for segment config export', error);
  }
};

const retrieveData = async (url: string) => {
  try {
    // Ensure there is no CORS issue
    const httpsUrl = url.replace(/^http:/, 'https:');
    // Get data
    const response: AxiosResponse<ArrayBuffer> = await axios.get(httpsUrl, {
      responseType: 'arraybuffer',
    });
    console.log('Server retrieved data at URL', url);

    return response;
  } catch (error) {
    console.error('Server error for retrieving data at URL', url, error);
  }
};

const decodePngArray = async (pngArray: ArrayBuffer) => {
  const blob = new Blob([pngArray], { type: 'image/png' });
  const bitmap = await createImageBitmap(blob);

  const canvas = document.createElement('canvas');
  canvas.width = bitmap.width;
  canvas.height = bitmap.height;
  const ctx = canvas.getContext('2d');
  ctx.drawImage(bitmap, 0, 0);

  const { data } = ctx.getImageData(0, 0, bitmap.width, bitmap.height);
  const pixelData = new Float32Array(bitmap.width * bitmap.height);
  for (let i = 0; i < pixelData.length; i++) {
    // Convert from pixel value to intensity
    pixelData[i] = data[4 * i] * 16 - 1000;
  }

  return { width: bitmap.width, height: bitmap.height, pixelData };
};

const createSegmentationFromConfig = async (
  segmentationId: string,
  segmentationConfig: ConfigJson[]
) => {
  const {
    segmentationService,
    viewportGridService,
    displaySetService,
    cornerstoneViewportService,
  } = servicesManager.services;

  // Delete former generated segmentations
  if (segmentationService.getSegmentation(segmentationId)) {
    segmentationService.remove(segmentationId);
  }

  // Initialize segments and color LUT
  const segments: cstTypes.Segment[] = [];
  const colorLUT: csTypes.ColorLUT = CORNERSTONE_COLOR_LUT.slice();
  for (const segment of segmentationConfig) {
    segments[segment.segment_index] = {
      segmentIndex: segment.segment_index,
      label: segment.label,
      locked: false,
      cachedStats: {},
      active: segment.segment_index === segmentationConfig[0].segment_index,
    };
    if (segment.color) {
      // @ts-expect-error - in cornerstone, the case of colorLUT of length 3 is handled
      colorLUT[segment.segment_index] = hexToRgbValue(segment.color);
    }
  }

  // Initialize generated segmentation
  const displaySetUID = viewportGridService.getDisplaySetsUIDsForViewport('axial')[0];
  const displaySet = displaySetService.getDisplaySetByUID(displaySetUID);
  const options = { segmentationId, segments, label: 'Segmentation ' + segmentationId };
  await segmentationService.createLabelmapForDisplaySet(displaySet, options);

  // Initialize segmentation representation
  const colorLUTIndex = getNextColorLUTIndex();
  addColorLUT(colorLUT, colorLUTIndex);
  segmentationService._segmentationIdToColorLUTIndexMap.set(segmentationId, colorLUTIndex);

  // TODO Ensure viewports are accessible
  const pulpSegment = segments.find(segment => segment?.label === 'Pulp');
  for (const viewportId of ['axial', 'sagittal', 'coronal']) {
    if (!cornerstoneViewportService.getViewportIds().includes(viewportId)) {
      continue;
    }
    await segmentationService.addSegmentationRepresentation(viewportId, {
      segmentationId,
      type: cstEnums.SegmentationRepresentations.Labelmap,
    });
    if (pulpSegment) {
      const { segmentIndex } = pulpSegment;
      segmentationService.setSegmentVisibility(viewportId, segmentationId, segmentIndex, false);
    }
    segmentationService.setActiveSegmentation(viewportId, segmentationId);
  }

  // The implants are shown in the 3D viewport from the start. The other
  // segmentations wait for their data: updateSegmentedVolume refreshes them,
  // a surface computed on their empty labelmap leaves the 3D viewport blank.
  if (segmentationId === 'implants') {
    segmentationService.refreshSurfaceRepresentation(segmentationId);
  }
};

const updateSegmentedVolume = async (
  segmentationId: string,
  segmentedVolumeArray: ArrayBuffer | Uint8Array,
  isCompressed: boolean = true
): Promise<Uint8Array<ArrayBuffer>> => {
  const { segmentationService, cornerstoneViewportService, panoramicService } =
    servicesManager.services;

  // Get the minimum layer index
  const { volume } = cornerstoneViewportService.getViewportInfo('axial').getViewportData()
    .data[0] as VolumeData;
  const { voxelManager, dimensions } = volume;
  const scalarData = voxelManager.getCompleteScalarDataArray();
  const [layerWidth, layerHeight, nbLayers] = dimensions;
  const offsetMin = (scalarData as any).findIndex((value: number) => value > -1000);
  const minLayer = Math.floor(offsetMin / layerWidth / layerHeight);
  const minIndex = minLayer * layerWidth * layerHeight;

  // Fill segmentation scalar data
  const segScalarData = new Uint8Array(layerWidth * layerHeight * nbLayers).fill(0);
  if (isCompressed) {
    const segmentedArray: Uint8Array<ArrayBuffer> = pako.inflate(segmentedVolumeArray);
    for (let i = 0; i < segScalarData.length - minIndex; i++) {
      segScalarData[minIndex + i] = segmentedArray[i];
    }
  } else {
    for (let i = 0; i < segScalarData.length; i++) {
      segScalarData[i] = segmentedVolumeArray[i];
    }
  }

  const { voxelManager: segVoxelManager } = segmentationService.getLabelmapVolume(segmentationId);
  segVoxelManager.setCompleteScalarDataArray(segScalarData);

  // Also initialize hidden segmentation
  const segmentation = segmentationService.getSegmentation(segmentationId);
  if (panoramicService.isDisplayed()) {
    await panoramicService.initializeDentascanSegmentations([segmentation]);
  }

  await segmentationService.refreshSurfaceRepresentation(segmentationId);

  return segScalarData;
};

const updateDiseases = async (diseases: ResultJson['diseases']) => {
  const { viewportGridService, panoramicService } = servicesManager.services;

  const displaySetUID = viewportGridService.getDisplaySetsUIDsForViewport('axial')[0];
  const panoramicState = panoramicService.getPanoramicState(displaySetUID);
  panoramicService.setPanoramicState(displaySetUID, { ...panoramicState, diseases });
};

const restoreImplants = async (implants: ImplantData[]) => {
  const { viewportGridService, panoramicService } = servicesManager.services;

  const displaySetUID = viewportGridService.getDisplaySetsUIDsForViewport('axial')[0];
  const panoramicState = panoramicService.getPanoramicState(displaySetUID);
  panoramicService.setPanoramicState(displaySetUID, { ...panoramicState, implants });

  await panoramicService.updateImplantsMask();
  await servicesManager.services.segmentationService.refreshSurfaceRepresentation('implants');
};

const updatePanoramicAndDentascans = async (
  panoramicArray: ArrayBuffer,
  metadata: { dentascan_thickness: number; min_max_tissue_layer: NumberPair; points: Points }
) => {
  const { viewportGridService, panoramicService } = servicesManager.services;
  const { points, min_max_tissue_layer, dentascan_thickness } = metadata;

  const { pixelData } = await decodePngArray(panoramicArray);
  updatePanoramic(min_max_tissue_layer, dentascan_thickness, points, pixelData, servicesManager);

  const displaySetUID = viewportGridService.getDisplaySetsUIDsForViewport('axial')[0];
  if (panoramicService.isDisplayed()) {
    panoramicService.initDisplay(displaySetUID);
  }
};

const handleCBCTSegmentedVolumeFinished = async (accessToken: string, uuid: string) => {
  // TODO: temporaire pour l'application, à vérifier quand on mettra à jour (3.9 actuellement)
  // if (once) {
  //   once = false;
  //   return;
  // }

  const { cornerstoneCacheService, databaseService } = servicesManager.services;

  // TODO use url sent by backend
  const segURLResponse = await retrieveCBCTSegmentationURL(accessToken, uuid);
  if (segURLResponse) {
    const { segmented_anatomy: segmentedAnatomyURL, segmented_diseases: segmentedDiseasesURL } =
      segURLResponse.data;

    // TODO called twice
    const { segmentationConfigs } = cornerstoneCacheService.getCbctSegmentationMetadata();
    createSegmentationFromConfig(
      'implants',
      segmentationConfigs.anatomy.filter(s => s.label === 'Implant')
    );
    createSegmentationFromConfig('diseases', segmentationConfigs.diseases);
    createSegmentationFromConfig('anatomy', segmentationConfigs.anatomy);

    let segmentedResponse: AxiosResponse<ArrayBuffer> = await retrieveData(segmentedDiseasesURL);
    if (segmentedResponse) {
      const segScalarData = await updateSegmentedVolume('diseases', segmentedResponse.data);
      await databaseService.modifyAnalyzeSegmentedDiseases(pako.deflate(segScalarData));
    }
    segmentedResponse = await retrieveData(segmentedAnatomyURL);
    if (segmentedResponse) {
      const segScalarData = await updateSegmentedVolume('anatomy', segmentedResponse.data);
      await databaseService.modifyAnalyzeSegmentedAnatomy(pako.deflate(segScalarData));
    }
    databaseService.modifyAnalyzeStatus('ANALYSED');
  }
};

const handleCBCTDiseasesFinished = async (accessToken: string, uuid: string) => {
  const { databaseService } = servicesManager.services;

  const segURLResponse = await retrieveCBCTSegmentationURL(accessToken, uuid);
  if (segURLResponse) {
    const { panoramic, metadata, diseases } = segURLResponse.data;

    updateDiseases(diseases);
    databaseService.modifyAnalyzeDiseases(diseases);

    const { control_points, curve_points, outer_points, inner_points, normals } = metadata.points;
    // Points are stored from left->right in backend but right->left in frontend
    const newMetadata = {
      dentascan_thickness: metadata.dentascan_thickness,
      min_max_tissue_layer: metadata.min_max_tissue_layer,
      points: {
        controlPoints: control_points.reverse(),
        curvePoints: curve_points.reverse(),
        outerPoints: outer_points.reverse(),
        innerPoints: inner_points.reverse(),
        normals: normals.reverse(),
      },
    };
    const panoramicArrayResponse = await retrieveData(panoramic);

    if (panoramicArrayResponse) {
      const panoramicArray = panoramicArrayResponse.data;
      updatePanoramicAndDentascans(panoramicArray, newMetadata);
    }
    databaseService.setRequestStatus('4/5 : Waiting for final segmentation');
  }
};

const createSocket = (accessToken: string, uuid: string) => {
  const { databaseService } = servicesManager.services;

  try {
    const socket = new WebSocket(`wss://${URLWebSocket}/socket/`, accessToken);
    console.log('Server socket:', socket);

    let isFirstSegmentation = true;

    socket.addEventListener('open', () => {
      console.log('Server socket - open');
      databaseService.createAnalysis(uuid);
    });

    socket.addEventListener('message', async event => {
      const { type, data }: { type: string; data: Data } = JSON.parse(event.data);
      if (data.uuid === uuid) {
        console.log('Server socket - message:', type, data);
        if (type === 'CBCT_SEGMENTED_VOLUME_FINISHED') {
          const segmentationLoaded = handleCBCTSegmentedVolumeFinished(accessToken, uuid);

          if (isFirstSegmentation) {
            databaseService.setRequestStatus('3/5 : Waiting for panoramic');
            isFirstSegmentation = false;
          } else {
            segmentationLoaded.then(() => databaseService.setAnalysisReady(true));
            databaseService.setRequestStatus('5/5 : Finished');
            setTimeout(() => databaseService.setRequestStatus(''), 5000);
            socket.close();
          }
        } else if (type === 'CBCT_DISEASES_FINISHED') {
          // Also updates panoramic and dentascans
          handleCBCTDiseasesFinished(accessToken, uuid);
        }
      }
    });

    socket.addEventListener('close', event => {
      console.log('Server socket - close:', event.code);
    });
  } catch (error) {
    console.error('Server socket error:', error);
  }
};

const loadAnalysisFromDatabase = async (analysis: ResultInfoFull) => {
  const { panoramicService, databaseService, cornerstoneCacheService } = servicesManager.services;
  const { panoramic, segmented_anatomy, segmented_diseases, diseases, implants, metadata } =
    analysis.data3d;

  // Load the diseases
  updateDiseases(diseases);

  // Load the panoramic
  const buffer = bufferFromStoredBinary(panoramic, 'panoramic');
  const floatArray = new Float32Array(buffer.buffer, buffer.byteOffset, buffer.byteLength / 4);
  updatePanoramic(
    metadata.min_max_tissue_layer,
    metadata.dentascan_thickness,
    metadata.points,
    floatArray,
    servicesManager,
    true
  );
  databaseService.setRequestStatus('2/4 : Waiting for segmentation');

  // TODO called twice
  const { segmentationConfigs } = cornerstoneCacheService.getCbctSegmentationMetadata();
  createSegmentationFromConfig(
    'implants',
    segmentationConfigs.anatomy.filter(s => s.label === 'Implant')
  );
  createSegmentationFromConfig('diseases', segmentationConfigs.diseases);
  createSegmentationFromConfig('anatomy', segmentationConfigs.anatomy);

  // Load the segmentations
  await new Promise(resolve => setTimeout(resolve, 5000));
  await updateSegmentedVolume(
    'diseases',
    pako.inflate(bufferFromStoredBinary(segmented_diseases, 'segmented_diseases')),
    false
  );
  await updateSegmentedVolume(
    'anatomy',
    pako.inflate(bufferFromStoredBinary(segmented_anatomy, 'segmented_anatomy')),
    false
  );
  if (implants?.length) {
    await restoreImplants(implants);
  }
  databaseService.setRequestStatus('3/4 : Waiting for image comment');

  // Load the comment of the volume
  const description = await databaseService.getImageDescription();
  panoramicService.setComment(description, false);

  databaseService.setAnalysisReady(true);
  databaseService.setRequestStatus('4/4 : Finished');
  setTimeout(() => databaseService.setRequestStatus(''), 5000);
  console.log('Finished loading analysis from database');
};

const serverInitialization = async (acceptedFiles: File[]) => {
  const { cornerstoneCacheService, databaseService } = servicesManager.services;
  databaseService.setAnalysisReady(false);

  const response = await authentifyUser();
  if (!response) {
    return;
  }
  // Set the metadata
  const accessKey: string = response.data.access;
  databaseService.setAccessKey(accessKey);
  const diseasesCategoriesResponse = await retrieveCategories(accessKey);
  const diseasesCategories: DiseasesCategories = diseasesCategoriesResponse.data['Disease'];
  const segmentationConfigsResponse = await retrieveConfigs(accessKey);
  const segmentationConfigs: Configs = segmentationConfigsResponse.data;

  const connectionString = databaseService.getConnectionString();
  const imageId = databaseService.getImageId();
  const analysisId = databaseService.getAnalysisId();
  const isFromDatabase = imageId !== -1 && connectionString && analysisId !== -1;
  let analysis: ResultInfoFull;

  let cbctSegmentationUUID: string;
  if (isFromDatabase) {
    analysis = await databaseService.getAnalyzeById();
    cbctSegmentationUUID = analysis.analyze_uuid;
  } else {
    databaseService.setRequestStatus('1/5 : Sending volume to server');
    const volumeTransferResponse = await transferVolumeOnDrop(acceptedFiles, accessKey);
    databaseService.setRequestStatus('2/5 : Analyzing volume');
    cbctSegmentationUUID = volumeTransferResponse.data.uuid;
  }

  const cbctSegmentationMetadata = {
    accessKey,
    cbctSegmentationUUID,
    diseasesCategories,
    segmentationConfigs,
  };
  cornerstoneCacheService.setCbctSegmentationMetadata(cbctSegmentationMetadata);

  if (isFromDatabase) {
    databaseService.setRequestStatus('1/4 : Waiting for volume to be fully loaded (20sec)');

    // If the image and analysis already exist in the database, load them
    await new Promise(resolve => setTimeout(resolve, 20000)); // TODO: maybe find a better way to check that the volume is loaded
    loadAnalysisFromDatabase(analysis);
  } else {
    // Otherwise, transfer the volume to the back
    createSocket(accessKey, cbctSegmentationUUID);
  }
};

export { postConfig, serverInitialization };
