import React, { ReactNode, useState } from 'react';
import { Icons } from '@ohif/ui-next';

/**
 * Collapsible block with a header with an arrow, a title, and the content displayed below when the block is open.
 */
const WediagCollapsible = ({
  title,
  children,
  defaultOpen = true,
}: {
  title: ReactNode;
  children: ReactNode;
  defaultOpen?: boolean;
}) => {
  const [isOpen, setIsOpen] = useState(defaultOpen);

  return (
    <div className="w-full rounded-lg border border-[hsl(var(--primary)/0.30)] bg-[hsl(var(--muted)/0.8)]">
      <button
        type="button"
        className="text-default flex w-full select-none items-center gap-1 px-2 py-1 text-left font-bold"
        onClick={() => setIsOpen(!isOpen)}
        aria-expanded={isOpen}
      >
        <span className="grid h-5 w-5 shrink-0 place-items-center">
          {isOpen ? <Icons.ChevronDown /> : <Icons.ChevronRight />}
        </span>
        <span>{title}</span>
      </button>
      {isOpen && (
        <div className="flex flex-col items-center space-y-2 px-2 pb-2 [&_button]:bg-black">
          {children}
        </div>
      )}
    </div>
  );
};

export default WediagCollapsible;
